#pragma once

#include <stdint.h>
#include <carb/Defines.h>

namespace carb
{
namespace datastore
{
class IDataStore;

// Wrapper for configuring and creating a hierarchy of DataStore caches based on input settings,
// default preferred settings and current set of restrictions on combining them
class DataStoreConfigurator
{
public:
    struct Config
    {
        // Enable GRPC datastore
        bool m_allowGRPCDataStore = true;
        const char* m_grpcDnsName = nullptr;
        bool m_grpcUseTLS = true;

        // For OmniHub
        bool m_allowHubDataStore = true;

        // For Local DataStore
        bool m_allowLocalDataStore = true;
        const char* m_localCachePath = nullptr;
        uint64_t m_localMemoryCacheSize = 0;

        // For Nucleus backed DataStore
        bool m_allowNucleusDataStore = true;
        //bool m_enableRemoteCache = true;
        const char* m_remoteCachePath = nullptr;
        bool m_useRemoteCacheDiscoveryForWrites = false;
        const char* m_remoteCacheDiscoveryPath = nullptr;

        // For HSS DataStore.
        // HSSC integration is supplied by the caller via the factory function pointers below.
        // This keeps DataStoreConfigurator free of any HSSC header dependency. If
        // m_hsscDataStoreFactory is null, the HSSC branch is silently skipped.
        bool m_allowHsscDataStore = true;
        const char* m_hsscUriStr = nullptr;
        const char* m_hsscDnsName = nullptr;
        const char* m_hsscLogFile = nullptr;
        uint32_t m_hsscConnPoolSize = 0;

        // Factory that builds the HSSC client and an HSSC-backed IDataStore from the
        // m_hssc* fields above. Returns the IDataStore (caller takes ownership and must
        // release via IDataStore::release) and writes an opaque client handle into
        // *outOpaqueClient (later passed to m_hsscClientDestroy).
        using HsscDataStoreFactoryFn = carb::datastore::IDataStore* (*)(
            const Config& config, void** outOpaqueClient);
        // Destroys an opaque HSSC client handle previously produced by m_hsscDataStoreFactory.
        using HsscClientDestroyFn = void (*)(void* opaqueClient);

        HsscDataStoreFactoryFn m_hsscDataStoreFactory = nullptr;
        HsscClientDestroyFn    m_hsscClientDestroy    = nullptr;

        // To enable .csv profile dumping
        bool m_profile = false;
        const char* m_profileLogPath = nullptr;

        // To enable failure injection
        bool m_supportFailureInjection = false;
    };

    enum Features : uint32_t
    {
        OmniHub = (1 << 0),
        HighSpeed = (1 << 1),
        Local = (1 << 2),
        Network = (1 << 3),
        FailureInjection = (1 << 4),
        None = 0x0
    };

    DataStoreConfigurator(const char* name, const Config& config);
    ~DataStoreConfigurator();

    carb::datastore::IDataStore* getDataStore();
    Features getFeatures() const;

    static bool supportsOmniHub();
private:
    bool createDataStores(const Config& config);
    void destroyDataStores();

    const char* m_name = "";
    carb::datastore::IDataStore* m_dataStore = nullptr;
    void* m_hsscClientOpaque = nullptr;
    Config::HsscClientDestroyFn m_hsscClientDestroy = nullptr;
    Features m_features = Features::None;
};

} // namespace datastore
} // namespace carb

#include "DataStoreConfigurator.inl"
